/**
 * Short names for the generated API types. Every API type comes from schema.d.ts
 * (generated by `make api-client`); this file only aliases them, it never defines one.
 */
import type { components } from "./schema"

type Schemas = components["schemas"]

export type SessionOut = Schemas["SessionOut"]
export type UserOut = Schemas["UserOut"]
export type AuthConfigOut = Schemas["AuthConfigOut"]
export type ProjectOut = Schemas["ProjectOut"]
export type ProviderOut = Schemas["ProviderOut"]
export type CredentialOut = Schemas["CredentialOut"]
export type CredentialCreate = Schemas["CredentialCreate"]
export type ModelProfileOut = Schemas["ModelProfileOut"]
export type CostSummary = Schemas["CostSummary"]
